import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"当时忍住就好了","description":"从冲动触发、暂停回应、表达边界和事后修复理解情绪管理，区分克制与压抑。","frontmatter":{"title":"当时忍住就好了","description":"从冲动触发、暂停回应、表达边界和事后修复理解情绪管理，区分克制与压抑。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 个人成长、心理学与健康生活 · 心智与习惯","summary":"从冲动触发、暂停回应、表达边界和事后修复理解情绪管理，区分克制与压抑。","status":"active","related":[{"title":"高效能人士的七个习惯","link":"/life/personal/books/growth/seven-habits","kind":"书籍导读","scope":"general","audience":"general"},{"title":"哈佛大学性格自修课","link":"/life/personal/books/growth/harvard-character","kind":"书籍导读","scope":"general","audience":"general"},{"title":"正面管教","link":"/life/personal/books/growth/positive-discipline","kind":"书籍导读","scope":"general","audience":"general"},{"title":"日知手帖","link":"/life/personal/books/growth/daily-notebook","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"哈佛大学性格自修课","link":"/life/personal/books/growth/harvard-character"},"next":{"text":"正面管教","link":"/life/personal/books/growth/positive-discipline"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"哈佛大学性格自修课","link":"/life/personal/books/growth/harvard-character"},"next":{"text":"正面管教","link":"/life/personal/books/growth/positive-discipline"}},"headers":[],"relativePath":"life/personal/books/growth/emotional-control.md","filePath":"life/personal/books/growth/emotional-control.md"}'),l={name:"life/personal/books/growth/emotional-control.md"};function n(i,e,s,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="当时忍住就好了" tabindex="-1">当时忍住就好了 <a class="header-anchor" href="#当时忍住就好了" aria-label="Permalink to &quot;当时忍住就好了&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：个人成长、心理学与健康生活 → 心智与习惯。</strong> 按用户书单，这本书属于情绪管理与自控力方向。适合带着具体场景阅读：争论中脱口而出的话、焦虑时作出的决定，以及事后反复后悔的反应。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《当时忍住就好了》：书单所指作者与版本待确认。</strong> 可查到肯·林德纳（Ken Lindner）的中文同名出版物，也有一竿月著的同名书，不能仅凭题名指定作者。<a href="https://positivelifechoicepsychology.com/books/" target="_blank" rel="noopener noreferrer">肯·林德纳本人书目</a>确认其著有 <em>Your Killer Emotions</em>；<a href="https://library.xhsysu.edu.cn/__local/3/1C/21/C81C366B860D1ED0A63031B991D_A4306C0C_6CD038.pdf" target="_blank" rel="noopener noreferrer">中文馆藏记录</a>列有其中文同名书与ISBN 9787559430595。用户已确认本条与《哈佛大学性格自修课》是两本不同的书，因此独立保留；这一信息仍不足以推出本页具体对应哪位作者，专业资历待版权页核实。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>以下情绪管理主题适合希望反思普通争论、冲动承诺和事后后悔的成年人。具体版本的研究依据和适用范围仍需核实，不能从题名认定它属于专业心理治疗教材。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>缺少作者、出版社与 ISBN，暂不确认同名或相近题名的具体作品。<strong>版本待确认；以下为本站主题导读，不是原书目录。</strong> 下列方法属于本站阅读议题，不声称是作者原有章节或论点。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>阅读重点</th><th>可实践的问题</th></tr></thead><tbody><tr><td>识别触发</td><td>观察情绪爆发前的事件、身体信号及想法。</td><td>我最早在什么时候已经察觉自己不舒服？</td></tr><tr><td>暂停反应</td><td>为自己争取重新判断的时间，避免在激动时立即承诺或攻击。</td><td>能否先说明需要一点时间，再回来讨论？</td></tr><tr><td>区分感受与行为</td><td>承认愤怒、委屈等感受，同时选择怎样行动。</td><td>我有这种感受，是否就必须以当前方式表达？</td></tr><tr><td>表达需要</td><td>将责备转成对具体事件、影响和需求的说明。</td><td>对方是否知道我希望改变哪件事？</td></tr><tr><td>设置边界</td><td>不把“忍住”理解为长期接受羞辱、侵害或不合理要求。</td><td>哪些问题需要拒绝、离开或寻求支持？</td></tr><tr><td>事后修复</td><td>承认伤害、作出具体道歉，并调整下一次的应对安排。</td><td>除了后悔，我准备改变哪一个环节？</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 后悔常常把注意力停留在“早知道就好了”，但真正可改变的是下一次出现相似情境时的选择。情绪管理并不意味着没有情绪，也不意味着凡事忍耐；它关注的是让感受、判断和行动之间保留空间。</p><p>阅读记录可以围绕一次具体冲突展开，写出触发、回应、结果与替代方案。这样更容易看见可改进的细节，而不是把一次失控扩大成对自我的整体否定。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 暂停的意义，是让下一步更接近自己的需要，而不是否认已经产生的情绪。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 为一次愿意复盘的分歧记录触发事件、当时解释、实际回应与结果，再列一个更具体的表达方式。把“我要控制脾气”改成一个可观察的回应；此为本站反思练习，不归为未知作者的方法。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>“忍住”可能让读者误把自控理解为长期压抑，需查看原文如何处理需求和边界。版本不明时也无法评价案例与理论是否充分。<strong>推荐语：</strong> 可围绕一次冲动决定做具体复盘；对这一本的内容推荐仍需确认作者与版本。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://search.worldcat.org/search?q=%E5%BD%93%E6%97%B6%E5%BF%8D%E4%BD%8F%E5%B0%B1%E5%A5%BD%E4%BA%86" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：用于确认作品身份与版本，当前未确认目录。</li><li>实物版权页和目录页应先于网络摘句；未注明出处的情绪管理语录不能当作本书原文。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const g=t(l,[["render",n]]);export{b as __pageData,g as default};
